const body = $input.first().json.body ?? {};
if (typeof body.lead_id !== 'string' || !body.lead_id.startsWith('demo-')) throw new Error('A synthetic demo lead_id is required');
if (!['approve','reject'].includes(body.decision)) throw new Error('decision must be approve or reject');
const approved = body.decision === 'approve';
return [{json:{lead_id:body.lead_id,review_status:approved?'approved':'rejected',crm_handoff:approved?'ready_for_authorized_handoff':'blocked',outreach_sent:false,demo_mode:true,note:approved?'Synthetic approval recorded. No CRM write or outreach is performed.':'Synthetic lead rejected. No CRM write or outreach is performed.'}}];
